// Independent public-fixture journal reference; no target IO or trust discovery.
import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';import {fileURLToPath,pathToFileURL} from 'node:url';
let root=path.dirname(fileURLToPath(import.meta.url));while(!fs.existsSync(path.join(root,'device-authority.lock.json'))){const up=path.dirname(root);if(up===root)throw Error('Missing pin');root=up;}
const pin=JSON.parse(fs.readFileSync(path.join(root,'device-authority.lock.json'),'utf8'));
const auth=await import(pathToFileURL(path.join(root,pin.path,'reference.mjs')).href);const {cbor}=auth;
export const BANK=8192,SIZE=24576,CAPACITY=8128,MAX_RECORDS=24;
const magic=Buffer.from('OCTAAS01'),names=['environment','resource_uuid','resource_role','resource_key_sha256','resource_key_revision'];
const purposes={ownership_receipt:1,phone_controller:2,core_link:3};
function fail(){throw Error('Authority storage operation denied');}
const sha=b=>createHash('sha256').update(b).digest();
function uint(n,min=1){if(!Number.isInteger(n)||n<min||n>4294967295)fail();return n;}
function uuid(s){if(typeof s!=='string'||!(/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/).test(s))fail();return Buffer.from(s.replaceAll('-',''),'hex');}
export function binding(b){if(!b||Object.keys(b).sort().join()!==[...names].sort().join()||!['development','production'].includes(b.environment)||!['Link','Core'].includes(b.resource_role))fail();uuid(b.resource_uuid);if(typeof b.resource_key_sha256!=='string'||!(/^[0-9a-f]{64}$/).test(b.resource_key_sha256)||/^0+$/.test(b.resource_key_sha256))fail();uint(b.resource_key_revision);return {...b};}
const prefix=b=>{b=binding(b);return [1,b.environment==='development'?1:2,uuid(b.resource_uuid),b.resource_role==='Link'?1:2,Buffer.from(b.resource_key_sha256,'hex'),b.resource_key_revision];};
export function crc(data){let n=0xffffffff;for(const v of data){n^=v;for(let j=0;j<8;j++)n=(n>>>1)^((n&1)?0xedb88320:0);}return (n^0xffffffff)>>>0;}
export function uncbor(data){let at=0;function read(depth=0){if(depth>20||at>=data.length)fail();const initial=data[at++],major=initial>>>5,ai=initial&31;let n=ai;if(ai>=24){const size={24:1,25:2,26:4}[ai];if(!size||at+size>data.length)fail();n=data.readUIntBE(at,size);at+=size;if(n<({24:24,25:256,26:65536}[ai]))fail();}if(major===0)return n;if(major===1)return -1-n;if(major===2||major===3){if(at+n>data.length)fail();const b=data.subarray(at,at+n);at+=n;return major===2?Buffer.from(b):b.toString('utf8');}if(major===4){if(n>data.length)fail();return Array.from({length:n},()=>read(depth+1));}if(major===5){if(n>data.length)fail();const m=new Map();for(let i=0;i<n;i++){const k=read(depth+1);if(m.has(k))fail();m.set(k,read(depth+1));}return m;}fail();}const out=read();if(at!==data.length||!cbor(out).equals(data))fail();return out;}
export class Context{
 constructor(local,registry,issuers){this.local=binding(local);this.registry=registry;this.issuers=issuers;}
 entry(raw){try{if(!Buffer.isBuffer(raw)||raw.length>270||!raw.length)fail();const p=uncbor(uncbor(raw.subarray(1))[2]),id=p.get(6).toString('hex').replace(/^(.{8})(.{4})(.{4})(.{4})(.{12})$/,'$1-$2-$3-$4-$5');const configured=binding(this.registry[id]);if(configured.environment!==this.local.environment)fail();const {environment,...expected}=configured;const a=auth.verify(raw,environment,this.issuers,expected),f=a.fields;
 if(f.purpose==='phone_controller'&&(this.local.resource_role!=='Link'||f.resource_uuid!==this.local.resource_uuid))fail();if(f.purpose==='core_link'&&((this.local.resource_role==='Core'&&f.resource_uuid!==this.local.resource_uuid)||(this.local.resource_role==='Link'&&f.state==='grant'&&f.link_uuid!==this.local.resource_uuid)))fail();return {raw,a,key:purposes[f.purpose]+':'+id};}catch{fail();}}
 encode(raws){if(!Array.isArray(raws)||raws.length>MAX_RECORDS)fail();const entries=raws.map(x=>this.entry(x)).sort((a,b)=>a.key.localeCompare(b.key));if(new Set(entries.map(x=>x.key)).size!==entries.length)fail();const payload=cbor([...prefix(this.local),entries.map(x=>x.raw)]);if(payload.length>CAPACITY)fail();return {payload,entries};}
 decode(data){if(!Buffer.isBuffer(data)||!data.length||data.length>CAPACITY)fail();const v=uncbor(data);if(!Array.isArray(v)||v.length!==7||!cbor(v.slice(0,6)).equals(cbor(prefix(this.local))))fail();const s=this.encode(v[6]);if(!data.equals(s.payload))fail();return s;}
 find(s,p,id){return s.entries.find(e=>e.a.fields.purpose===p&&e.a.fields.resource_uuid===id)?.a;}
 owners(s,a){const f=a.fields;auth.checkOwners(a,this.find(s,'ownership_receipt',f.resource_uuid),f.purpose==='core_link'&&f.state==='grant'?this.find(s,'ownership_receipt',f.link_uuid):undefined);}
 transition(old,next){const previous=new Map(old.entries.map(e=>[e.key,e]));const current=new Map(next.entries.map(e=>[e.key,e]));if([...previous.keys()].some(k=>!current.has(k)))fail();for(const [k,e] of current){const result=auth.compareRevision(e.a,previous.get(k)?.a);if(result!=='retry'&&e.a.fields.purpose!=='ownership_receipt')this.owners(next,e.a);}}
 merge(old,raw){const e=this.entry(raw),previous=old.entries.find(x=>x.key===e.key);if(previous&&auth.compareRevision(e.a,previous.a)==='retry')return old;const next=this.encode([...old.entries.filter(x=>x.key!==e.key).map(x=>x.raw),raw]);this.transition(old,next);return next;}
 eligible(s,p,id){const a=this.find(s,p,id);if(!a||a.fields.state!=='grant')return false;try{this.owners(s,a);return true;}catch{return false;}}
}
export function bankBytes(generation,payload){uint(generation);if(!Buffer.isBuffer(payload)||!payload.length||payload.length>CAPACITY)fail();const out=Buffer.alloc(BANK,255);magic.copy(out);out.writeUInt32LE(1,8);out.writeUInt32LE(generation,12);out.writeUInt32LE(payload.length,16);sha(payload).copy(out,20);out.writeUInt32LE(crc(out.subarray(0,52)),52);out.fill(0,56,60);payload.copy(out,64);return out;}
export function parseBank(data,context){if(!Buffer.isBuffer(data)||data.length!==BANK)fail();if(data.every(v=>v===255))return null;if(!data.subarray(56,60).equals(Buffer.alloc(4)))return 'torn';const gen=data.readUInt32LE(12),length=data.readUInt32LE(16);if(!data.subarray(0,8).equals(magic)||data.readUInt32LE(8)!==1||!gen||length<1||length>CAPACITY||!data.subarray(60,64).every(v=>v===255))fail();const p=data.subarray(64,64+length);if(data.readUInt32LE(52)!==crc(data.subarray(0,52))||!sha(p).equals(data.subarray(20,52))||!data.subarray(64+length).every(v=>v===255))fail();return {generation:gen,snapshot:context.decode(p)};}
export function load(image,context){try{if(!Buffer.isBuffer(image)||image.length!==SIZE)fail();const rows=[0,1,2].map(i=>parseBank(image.subarray(i*BANK,(i+1)*BANK),context));const valid=rows.map((r,i)=>({r,i})).filter(x=>x.r&&x.r!=='torn');if(!valid.length)return {status:rows.every(x=>x===null)?'Unprepared':'Fault',generation:0};const gens=[...new Set(valid.map(x=>x.r.generation))].sort((a,b)=>a-b);if(gens.at(-1)-gens[0]>1)fail();const groups=new Map();for(const {r,i} of valid){if(groups.has(r.generation)&&!groups.get(r.generation).snapshot.payload.equals(r.snapshot.payload))fail();if(!groups.has(r.generation))groups.set(r.generation,{snapshot:r.snapshot,copies:[]});groups.get(r.generation).copies.push(i);}if(gens.length===2)context.transition(groups.get(gens[0]).snapshot,groups.get(gens[1]).snapshot);const generation=gens.at(-1),g=groups.get(generation);if(g.copies.length>=2)return {status:'Ready',generation,...g};if((generation===1&&!g.snapshot.entries.length)||gens.length===2)return {status:'Pending',generation,...g};fail();}catch{return {status:'Fault',generation:0};}}

if(process.argv[1]&&import.meta.url===pathToFileURL(process.argv[1]).href){const v=JSON.parse(fs.readFileSync(process.argv[2],'utf8')),rows=new Map(v.authorities.map(x=>[x.name,x])),snapshots=new Map();
 for(const s of v.snapshots){const c=new Context(s.local,s.registry,v.issuers),snapshot=c.encode(s.records.map(n=>Buffer.from(rows.get(n).hex,'hex')));assert.equal(snapshot.payload.toString('hex'),s.hex,s.name);const bank=bankBytes(s.generation,snapshot.payload);assert.equal(bank.subarray(0,64).toString('hex'),s.header_hex,s.name);assert.equal(sha(bank).toString('hex'),s.bank_sha256,s.name);assert.equal(c.decode(snapshot.payload).entries.length,s.records.length);snapshots.set(s.name,{s,c,snapshot});}
 for(const t of v.transitions){const a=snapshots.get(t.before),b=snapshots.get(t.after),op=()=>a.c.transition(a.snapshot,b.snapshot);if(t.result==='deny')assert.throws(op);else op();}
 for(const r of v.merges){const a=snapshots.get(r.snapshot),op=()=>a.c.merge(a.snapshot,Buffer.from(rows.get(r.record).hex,'hex'));if(r.result==='deny')assert.throws(op);else assert.equal(op().payload.toString('hex'),snapshots.get(r.result).snapshot.payload.toString('hex'));}
 for(const row of v.images){const base=snapshots.get(row.context),image=Buffer.alloc(SIZE,255);for(const patch of row.patches)Buffer.from(patch.hex,'hex').copy(image,patch.offset);const r=load(image,base.c);assert.equal(r.status,row.status,row.name);assert.equal(r.generation,row.generation,row.name);}
 for(const row of v.eligible){const a=snapshots.get(row.snapshot);assert.equal(a.c.eligible(a.snapshot,row.purpose,row.resource_uuid),row.result,row.name);}
 for(const row of v.invalid_snapshots){const a=snapshots.get(row.context);assert.throws(()=>a.c.decode(Buffer.from(row.hex,'hex')),undefined,row.name);}
 console.log(JSON.stringify(Object.fromEntries(['snapshots','transitions','merges','images','eligible','invalid_snapshots'].map(n=>[n,v[n].length]))));}
